// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.mínimo = Number(String(obj.mínimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Dados recebidos (clientes + investimentos)
const clientes = $json.body.clientes;
const investimentos = $json.investimentos;

// Função para normalizar saldo (transformar "R$ 12.500,00" em número)
function normalizarSaldo(saldoStr) {
  return Number(
    saldoStr.replace(/[^\d]/g, "") // remove caracteres não numéricos
  );
}

// Gera recomendações
const mensagens = clientes.map(cliente => {
  const saldo = normalizarSaldo(cliente.saldo);

  // Filtra investimentos compatíveis com o perfil e saldo
  const opcoes = investimentos.filter(inv =>
    inv.perfil === cliente.perfil &&
    saldo >= Number(inv.minimo)
  );

  // Monta mensagem
  if (opcoes.length > 0) {
    const recomendacao = opcoes[0]; // pega a primeira opção válida
    return {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      mensagem: `Olá ${cliente.nome}! Pelo seu perfil (${cliente.perfil}), uma boa opção é o **${recomendacao.produto}** (mínimo R$ ${recomendacao.minimo}). Com seu saldo atual (${cliente.saldo}), você já consegue investir. Rentabilidade: ${recomendacao.rentabilidade}.`
    };
  } else {
    return {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      mensagem: `Olá ${cliente.nome}! Infelizmente, com seu saldo atual (${cliente.saldo}), não encontramos opções disponíveis para o perfil ${cliente.perfil}.`
    };
  }
});

// Retorna resultado para o n8n
return [{ json: { mensagens } }];

// Função para normalizar saldo (ex.: "R$ 12.500,00" -> 12500)
function normalizarSaldo(saldoStr) {
  return Number(saldoStr.replace(/[^\d]/g, ""));
}

// Base de regras de copy (padrão para todas as mensagens)
const copyRules = {
  idioma: "pt-BR",
  tom: "amigável e profissional",
  tamanho: "curto (4-6 linhas)",
  evitar: [
    "promessas de ganho",
    "garantias",
    "linguagem agressiva"
  ]
};

// Processa cada mensagem
const mensagensProcessadas = $json.mensagens.map(m => {
  const saldoNum = normalizarSaldo(m.saldo);

  // Extrai produto e rentabilidade da mensagem original
  const produtoMatch = m.mensagem.match(/\*\*(.*?)\*\*/);
  const produto = produtoMatch ? produtoMatch[1] : "Produto não identificado";

  const rentabilidadeMatch = m.mensagem.match(/Rentabilidade:\s*([^\.\n]+)/);
  const rentabilidade = rentabilidadeMatch ? rentabilidadeMatch[1] : "N/A";

  // Extrai mínimo (número após "mínimo R$")
  const minimoMatch = m.mensagem.match(/mínimo R\$ ([\d\.]+)/);
  const minimo = minimoMatch ? Number(minimoMatch[1].replace(/\./g, "")) : 0;

  // Define motivo
  const motivo = saldoNum >= minimo ? "saldo_ok" : "saldo_insuficiente";

  return {
    email_to: m.email,
    nome: m.nome,
    perfil: m.perfil,
    saldo_texto: m.saldo,
    saldo_num: saldoNum,
    recomendacao: {
      perfil: m.perfil,
      produto,
      mínimo: minimo,
      rentabilidade
    },
    motivo,
    mensagem_base: m.mensagem,
    copy_rules: copyRules
  };
});

// Retorna resultado para o n8n
return [{ json: { mensagensProcessadas } }];

// O input é um array com um objeto
const input = $json;

// Pega o primeiro item do array
const firstItem = Array.isArray(input) ? input[0] : input;

// Garante que existe o campo content.parts[0].text
if (!firstItem.content || !firstItem.content.parts || !firstItem.content.parts[0]) {
  throw new Error("Estrutura inesperada no input: não encontrei content.parts[0].text");
}

// Extrai o texto bruto
const rawText = firstItem.content.parts[0].text;

// Remove delimitadores ```json e ```
const cleaned = rawText.replace(/```json/, "").replace(/```/, "").trim();

// Converte para array de objetos
let emails;
try {
  emails = JSON.parse(cleaned);
} catch (e) {
  throw new Error("Erro ao converter o texto em JSON: " + e.message);
}

// Retorna cada objeto como item separado no output
return emails.map(e => ({ json: e }));

// ============================================
// SUBSTITUIÇÃO DE EMAIL ESPECÍFICO
// ============================================

const items = $input.all();

const EMAIL_ORIGINAL = 'joao@email.com';
const EMAIL_NOVO = 'soaresaj62@gmail.com';

return items.map(item => ({
  json: {
    ...item.json,
    email_to: item.json.email_to === EMAIL_ORIGINAL
      ? EMAIL_NOVO
      : item.json.email_to
  }
}));
